module TopModule (
    input  logic         clk,
    input  logic         load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    logic [255:0] grid_reg;
    logic [255:0] next_grid;

    always_ff @(posedge clk) begin
        if (load) begin
            grid_reg <= data;
        end else begin
            grid_reg <= next_grid;
        end
    end

    assign q = grid_reg;

    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                int rm1, rp1, cm1, cp1;
                int neighbors;
                int idx;

                rm1 = (r == 0)  ? 15 : r - 1;
                rp1 = (r == 15) ? 0  : r + 1;
                cm1 = (c == 0)  ? 15 : c - 1;
                cp1 = (c == 15) ? 0  : c + 1;

                idx = r * 16 + c;

                neighbors = 
                    grid_reg[rm1 * 16 + cm1] + 
                    grid_reg[rm1 * 16 + c  ] + 
                    grid_reg[rm1 * 16 + cp1] +
                    grid_reg[r   * 16 + cm1] + 
                    grid_reg[r   * 16 + cp1] +
                    grid_reg[rp1 * 16 + cm1] + 
                    grid_reg[rp1 * 16 + c  ] + 
                    grid_reg[rp1 * 16 + cp1];

                if (neighbors == 3) begin
                    next_grid[idx] = 1'b1;
                end else if (neighbors == 2) begin
                    next_grid[idx] = grid_reg[idx];
                end else begin
                    next_grid[idx] = 1'b0;
                end
            end
        end
    end

endmodule

