module TopModule (
    input  logic         clk,
    input  logic         load,
    input  logic [255:0] data,
    output logic [255:0] q
);

    logic [0:15][0:15] current_grid;
    logic [0:15][0:15] next_grid;

    // Unpack q and data
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                current_grid[r][c] = q[r*16 + c]; // wait, q[15:0] is row 0?
            end
        end
    end

    // Wait, q should be output driven by register.
    logic [0:15][0:15] grid_reg;

    always_ff @(posedge clk) begin
        if (load) begin
            for (int r = 0; r < 16; r++) begin
                for (int c = 0; c < 16; c++) begin
                    grid_reg[r][c] <= data[r*16 + c];
                end
            end
        end else begin
            grid_reg <= next_grid;
        end
    end

    // Pack q
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                q[r*16 + c] = grid_reg[r][c];
            end
        end
    end

    // Compute next_grid
    always_comb begin
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                int rm1, rp1, cm1, cp1;
                int neighbors;

                rm1 = (r == 0)  ? 15 : r - 1;
                rp1 = (r == 15) ? 0  : r + 1;
                cm1 = (c == 0)  ? 15 : c - 1;
                cp1 = (c == 15) ? 0  : c + 1;

                neighbors = 
                    grid_reg[rm1][cm1] + grid_reg[rm1][c] + grid_reg[rm1][cp1] +
                    grid_reg[r][cm1]   +                    grid_reg[r][cp1]   +
                    grid_reg[rp1][cm1] + grid_reg[rp1][c] + grid_reg[rp1][cp1];

                if (neighbors == 3) begin
                    next_grid[r][c] = 1'b1;
                end else if (neighbors == 2) begin
                    next_grid[r][c] = grid_reg[r][c];
                end else begin
                    next_grid[r][c] = 1'b0;
                end
            end
        end
    end

endmodule

