module tb_TopModule;
    logic         clk;
    logic         load;
    logic [255:0] data;
    logic [255:0] q;

    TopModule uut (
        .clk(clk),
        .load(load),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        load = 0;
        data = '0;

        // Test 1: Block (2x2 still life)
        // Put block at row 1, col 1: (1,1), (1,2), (2,1), (2,2)
        // row 1: bits 16..31. col 1 and 2 -> bits 17, 18
        // row 2: bits 32..47. col 1 and 2 -> bits 33, 34
        @(posedge clk);
        data = '0;
        data[1*16 + 1] = 1;
        data[1*16 + 2] = 1;
        data[2*16 + 1] = 1;
        data[2*16 + 2] = 1;
        load = 1;
        @(posedge clk);
        load = 0;

        @(posedge clk);
        // Should remain same
        assert(q[1*16 + 1] == 1);
        assert(q[1*16 + 2] == 1);
        assert(q[2*16 + 1] == 1);
        assert(q[2*16 + 2] == 1);

        @(posedge clk);
        assert(q[1*16 + 1] == 1);
        assert(q[1*16 + 2] == 1);
        assert(q[2*16 + 1] == 1);
        assert(q[2*16 + 2] == 1);

        // Test 2: Blinker oscillator
        // Horizontal line at row 5, cols 5,6,7 -> bits 5*16+5, 5*16+6, 5*16+7
        @(posedge clk);
        data = '0;
        data[5*16 + 5] = 1;
        data[5*16 + 6] = 1;
        data[5*16 + 7] = 1;
        load = 1;
        @(posedge clk);
        load = 0;

        @(posedge clk); // t=1: should become vertical line at cols 6, rows 4,5,6 -> 4*16+6, 5*16+6, 6*16+6
        #1;
        assert(q[4*16 + 6] == 1);
        assert(q[5*16 + 6] == 1);
        assert(q[6*16 + 6] == 1);
        assert(q[5*16 + 5] == 0);
        assert(q[5*16 + 7] == 0);

        @(posedge clk); // t=2: should become horizontal line again
        #1;
        assert(q[5*16 + 5] == 1);
        assert(q[5*16 + 6] == 1);
        assert(q[5*16 + 7] == 1);
        assert(q[4*16 + 6] == 0);
        assert(q[6*16 + 6] == 0);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

module tb_TopModule;
    logic         clk;
    logic         load;
    logic [255:0] data;
    logic [255:0] q;

    TopModule uut (
        .clk(clk),
        .load(load),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        load = 0;
        data = '0;

        // Test 1: Block (2x2 still life)
        @(posedge clk);
        data = '0;
        data[1*16 + 1] = 1;
        data[1*16 + 2] = 1;
        data[2*16 + 1] = 1;
        data[2*16 + 2] = 1;
        load = 1;
        @(posedge clk);
        load = 0;

        @(posedge clk);
        assert(q[1*16 + 1] == 1);
        assert(q[1*16 + 2] == 1);
        assert(q[2*16 + 1] == 1);
        assert(q[2*16 + 2] == 1);

        // Test 2: Toroidal wrap-around test
        // Cell at (0,0), (0,15), (15,0) forming a triangle/cluster that interacts across boundaries
        // (0,0) neighbours include (0,15) and (15,0) and (15,15).
        // Let's load (0,0), (0,15), (15,0)
        @(posedge clk);
        data = '0;
        data[0*16 + 0]  = 1; // (0,0)
        data[0*16 + 15] = 1; // (0,15)
        data[15*16 + 0] = 1; // (15,0)
        load = 1;
        @(posedge clk);
        load = 0;

        // Let's check neighbors of (0,0):
        // (0,15) [alive], (15,0) [alive], (15,15) [dead], (0,1) [dead], (15,1) [dead], (1,0) [dead], (1,15) [dead], (1,0) [dead]...
        // Total neighbors for (0,0) = 2 ((0,15) and (15,0)). Since state is 1, 2 neighbours -> stays 1.
        // Neighbors for (0,15):
        // (0,14), (0,0) [alive], (1,14), (1,15), (1,0), (15,14), (15,15), (15,0) [alive].
        // Total = 2. Stays 1.
        // Neighbors for (15,0):
        // (14,0), (14,1), (15,1), (0,0) [alive], (0,1), (14,15), (15,15), (0,15) [alive].
        // Total = 2. Stays 1.
        // What about (15,15)? Neighbors of (15,15):
        // (14,14), (14,15), (14,0), (15,14), (15,0) [alive], (0,14), (0,15) [alive], (0,0) [alive].
        // Total neighbors for (15,15) = 3! ((15,0), (0,15), (0,0)).
        // So (15,15) should become 1 at next cycle!
        @(posedge clk);
        #1;
        assert(q[15*16 + 15] == 1);

        $display("SELFTEST PASS");
        $finish;
    end

endmodule

