module tb_TopModule;
    logic         clk;
    logic         load;
    logic [255:0] data;
    logic [255:0] q;

    TopModule uut (
        .clk(clk),
        .load(load),
        .data(data),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        load = 0;
        data = '0;

        @(posedge clk);
        data = '0;
        data[0*16 + 0]  = 1; // (0,0) -> bit 0
        data[0*16 + 15] = 1; // (0,15) -> bit 15
        data[15*16 + 0] = 1; // (15,0) -> bit 240
        load = 1;
        @(posedge clk);
        load = 0;

        #1;
        $display("After load: q[0]=%b, q[15]=%b, q[240]=%b", q[0], q[15], q[240]);

        @(posedge clk);
        #1;
        $display("After 1 step: q[255] (15,15) = %b", q[15*16 + 15]);
        for (int r = 0; r < 16; r++) begin
            for (int c = 0; c < 16; c++) begin
                if (q[r*16 + c]) $display("Alive at (%0d, %0d)", r, c);
            end
        end

        $finish;
    end

endmodule

